function setCloudStatus(label,state=''){
  const el=document.querySelector('#cloudStatus'); if(!el)return;
  el.textContent=label; el.className='cloud-status '+state;
}
function sanitizeForCloud(db){
  const x=JSON.parse(JSON.stringify(db));
  if(x.settings?.heroBgImage===EMBEDDED_HERO_BG) x.settings.heroBgImage='__EMBEDDED_HERO__';
  if(x.settings?.hybridCard?.image===EMBEDDED_PUMP_BG) x.settings.hybridCard.image='__EMBEDDED_PUMP__';
  if(Array.isArray(x.users)) x.users=x.users.map(u=>{const y={...u};delete y.password;return y});
  const scrub=v=>{
    if(Array.isArray(v)) return v.map(scrub);
    if(v&&typeof v==='object'){Object.keys(v).forEach(k=>v[k]=scrub(v[k]));return v}
    if(typeof v==='string'&&v.startsWith('data:image/')&&v.length>180000) return '';
    return v;
  };
  return scrub(x);
}
function hydrateFromCloud(db){
  const x=JSON.parse(JSON.stringify(db||{}));
  if(x.settings?.heroBgImage==='__EMBEDDED_HERO__') x.settings.heroBgImage=EMBEDDED_HERO_BG;
  if(x.settings?.hybridCard?.image==='__EMBEDDED_PUMP__') x.settings.hybridCard.image=EMBEDDED_PUMP_BG;
  return x;
}
async function pushCloudNow(db){
  if(!cloudReady||!firebaseDb||!firebaseAuth?.currentUser)return false;
  try{
    const payload=sanitizeForCloud(db);
    await firebaseDb.collection('appData').doc('main').set({
      payload,
      updatedAt:firebase.firestore.FieldValue.serverTimestamp()
    },{merge:true});
    setCloudStatus('Online','online');
    return true;
  }catch(err){
    console.warn('Cloud save gagal',err);
    setCloudStatus('Sinkronisasi gagal','error');
    return false;
  }
}
function scheduleCloudSave(db){
  if(cloudApplying||!cloudReady||!firebaseAuth?.currentUser)return;
  clearTimeout(cloudPushTimer);
  const snapshot=JSON.parse(JSON.stringify(db));
  cloudPushTimer=setTimeout(()=>pushCloudNow(snapshot),500);
}
function startCloudSync(){
  if(!firebaseDb||cloudUnsubscribe)return;
  cloudUnsubscribe=firebaseDb.collection('appData').doc('main').onSnapshot(snap=>{
    if(!snap.exists){
      cloudSnapshotLoaded=true;
      setCloudStatus(firebaseAuth?.currentUser?'Siap sinkron':'Online publik','online');
      if(firebaseAuth?.currentUser)pushCloudNow(getDB());
      return;
    }
    const remote=snap.data()?.payload;
    if(!remote)return;
    cloudApplying=true;
    const hydrated=normalizeDB(hydrateFromCloud(remote));
    localStorage.setItem(DBKEY,JSON.stringify(hydrated));
    cloudApplying=false;
    cloudSnapshotLoaded=true;
    setCloudStatus('Online','online');
    renderPublic();
    if(currentUser()&&!document.querySelector('#dashboardView')?.hidden) navigateDash(currentDashPage||'home');
  },err=>{
    console.warn('Cloud sync gagal',err);
    setCloudStatus('Offline','error');
  });
}
async function initFirebaseOnline(){
  try{
    if(!window.firebase)throw new Error('Firebase SDK belum termuat');
    firebaseApp=firebase.apps?.length?firebase.app():firebase.initializeApp(FIREBASE_CONFIG);
    firebaseDb=firebase.firestore();
    firebaseAuth=firebase.auth();
    firebaseStorage=firebase.storage();
    cloudReady=true;
    try{firebaseDb.enablePersistence({synchronizeTabs:true}).catch(()=>{})}catch(e){}
    try{if(location.protocol!=='file:'&&firebase.analytics)firebase.analytics()}catch(e){}
    firebaseAuth.onAuthStateChanged(user=>{
      setCloudStatus(user?'Online':'Online publik','online');
      if(user&&cloudSnapshotLoaded)pushCloudNow(getDB());
    });
    startCloudSync();
  }catch(err){
    console.warn('Firebase init gagal',err);
    setCloudStatus('Mode lokal','error');
  }
}

