function clone(obj){ return JSON.parse(JSON.stringify(obj)); }
function normalizeDB(db){
  const out = clone(seed);
  if(!db || typeof db!=='object') return out;
  out.settings = {...out.settings,...(db.settings||{}),hybridCard:{...DEFAULT_HYBRID_CARD,...(db.settings?.hybridCard||{})}};
  const incomingHouses=db.settings?.houseCards||{};
  out.settings.houseCards={};
  ['open','semi','secure'].forEach(type=>{out.settings.houseCards[type]={...DEFAULT_HOUSE_CARDS[type],...(incomingHouses[type]||{})};});
  if(!out.settings.heroBgImage || /assets\/hero-sawah-riil/i.test(out.settings.heroBgImage)) out.settings.heroBgImage=EMBEDDED_HERO_BG;
  if(!out.settings.hybridCard.image || /assets\/pompa-sawah-riil/i.test(out.settings.hybridCard.image)) out.settings.hybridCard.image=EMBEDDED_PUMP_BG;
  ['products','beneficiaries','users','claims','audit'].forEach(k=>{ if(Array.isArray(db[k])) out[k]=db[k]; });
  // Production admin identity: email is public identity; password exists only in Firebase Authentication.
  let adminUser=out.users.find(u=>u.role==='admin') || out.users.find(u=>String(u.email||'').toLowerCase()===ADMIN_EMAIL);
  if(!adminUser){
    adminUser={id:'U001',name:'Administrator',email:ADMIN_EMAIL,password:'',role:'admin',status:'aktif'};
    out.users.unshift(adminUser);
  }
  adminUser.email=ADMIN_EMAIL;
  adminUser.role='admin';
  adminUser.status='aktif';
  adminUser.password='';
  out.users=out.users.filter((u,i,a)=>{
    const mail=String(u.email||'').toLowerCase();
    if(mail==='admin@listrikmasuksawah.id') return false;
    if(mail===ADMIN_EMAIL) return u===adminUser;
    return true;
  });
  out.beneficiaries.forEach(b=>{if(b.email==='penerima@demo.id')b.email='penerima@listrikmasuksawah.id';});
  out.users.forEach(u=>{if(u.email==='penerima@demo.id')u.email='penerima@listrikmasuksawah.id';});
  out.users=out.users.map(u=>{const seedUser=seed.users.find(s=>s.email===u.email);return {...u,password:u.role==='admin'?'':(u.password||seedUser?.password||'')}});
  if(!out.settings.footerText || out.settings.footerText==='Sistem informasi bantuan pompa irigasi hybrid.' || out.settings.footerText==='Mengalirkan Energi ke Sawah, Menguatkan Petani, Menumbuhkan Panen Negeri.') out.settings.footerText='Listrik untuk Sawah, Energi untuk Negeri.';
  out.products = out.products.map(p=>({image:'',active:true,...p})).map(p=>{
    if(p.name==='Pompa Irigasi Hybrid 4"') p.name='Pompa Irigasi Hybrid 6"';
    if(typeof p.spec==='string'){
      if(p.spec==='Diesel 12 HP + motor listrik 7,5 kW 3-phase') p.spec='Diameter 6 inchi • Diesel 12 HP + motor listrik 7,5 kW 3-phase';
      p.spec=p.spec.replace(/\b4\s*(inchi|inch|")/gi,'6 inchi');
    }
    if(typeof p.desc==='string') p.desc=p.desc.replace(/pompa irigasi hybrid diameter 4 inchi/gi,'pompa irigasi hybrid diameter 6 inchi');
    return p;
  });
  out.beneficiaries = out.beneficiaries.map(b=>({photo:'',warrantyMonths:12,userId:'',...b})).map(b=>{
    if(typeof b.asset==='string') b.asset=b.asset.replace(/Pompa Hybrid 4"/g,'Pompa Hybrid 6 inchi').replace(/Pompa Hybrid 4 inchi/gi,'Pompa Hybrid 6 inchi');
    return b;
  });
  out.claims = out.claims.map(c=>({adminNote:'',photo:'',status:'Dikirim',...c}));
  return out;
}
function getDB(){
  let raw=localStorage.getItem(DBKEY);
  if(!raw){
    const legacy=localStorage.getItem(LEGACY_DBKEY);
    if(legacy){ try{ const migrated=normalizeDB(JSON.parse(legacy)); saveDB(migrated); return migrated; }catch(e){} }
    const fresh=clone(seed); saveDB(fresh); return fresh;
  }
  try{return normalizeDB(JSON.parse(raw))}catch(e){const fresh=clone(seed);saveDB(fresh);return fresh}
}
function saveDB(db){const normalized=normalizeDB(db);localStorage.setItem(DBKEY,JSON.stringify(normalized));scheduleCloudSave(normalized)}
function renderAll(){ renderPublic(); const u=currentUser(); if(u && !$('#dashboardView').hidden) navigateDash(currentDashPage||'home'); }
function resetDB(){
  localStorage.setItem(DBKEY,JSON.stringify(clone(seed)));
  sessionStorage.removeItem(SESSION);
  renderPublic(); logout(false); toast('Data aplikasi berhasil direset');
}
function uid(prefix){return prefix+'-'+Math.random().toString(36).slice(2,8).toUpperCase()}
function warrantyCode(province='ID'){
  const p=(province||'ID').replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase().padEnd(3,'X');
  return `LMS-${p}-${Date.now().toString().slice(-6)}${Math.random().toString(36).slice(2,4).toUpperCase()}`;
}
function toast(msg){const t=$('#toast'); if(!t)return; t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function fmtDate(v){if(!v)return '-';try{return new Date(v+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}catch(e){return v}}
function addMonths(dateStr,m){const d=new Date(dateStr+'T00:00:00');d.setMonth(d.getMonth()+Number(m||12));return d}
function warrantyStatus(b){
  if(!b?.warrantyStart) return {label:'Belum Aktif',cls:'warn'};
  const end=addMonths(b.warrantyStart,b.warrantyMonths||12), now=new Date();
  return now<=end?{label:'Aktif',cls:'ok',end}:{label:'Berakhir',cls:'warn',end};
}
function slug(s){return (s||'').toLowerCase().replace(/\s+/g,'-')}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function safeUrl(url){ const v=String(url||'').trim(); return /^(https?:\/\/|data:image\/|assets\/|\.\/|\.\.\/)/i.test(v)?v:''; }
function safeColor(value,fallback){ const v=String(value||'').trim(); return /^#[0-9a-f]{6}$/i.test(v)?v:fallback; }
function hybridCardSettings(db=getDB()){ return {...DEFAULT_HYBRID_CARD,...(db.settings?.hybridCard||{})}; }
function hybridVisualMarkup(c){
  const core=safeColor(c.coreColor,DEFAULT_HYBRID_CARD.coreColor), diesel=safeColor(c.dieselColor,DEFAULT_HYBRID_CARD.dieselColor), electric=safeColor(c.electricColor,DEFAULT_HYBRID_CARD.electricColor);
  const img=safeUrl(c.image);
  if(c.useImage && img){
    return `<div class="hybrid-photo-visual"><img src="${img}" alt="${esc(c.pumpLabel)} ${esc(c.pumpName)}"><div class="hybrid-photo-caption"><b>${esc(c.pumpLabel)} ${esc(c.pumpName)}</b><span>${esc(c.dieselLabel)} ${esc(c.dieselPower)} ${esc(c.shaftSymbol)} ${esc(c.electricLabel)} ${esc(c.electricPower)}</span></div></div>`;
  }
  return `<div class="hybrid-visual"><div class="pump-core" style="background:linear-gradient(160deg,${core},#164c31)">${esc(c.pumpLabel)}<br><strong>${esc(c.pumpName)}</strong></div><div class="drive diesel" style="background:${diesel}">${esc(c.dieselLabel)}<br><small>${esc(c.dieselPower)}*</small></div><div class="shaft">${esc(c.shaftSymbol)}</div><div class="drive electric" style="background:${electric}">${esc(c.electricLabel)}<br><small>${esc(c.electricPower)}*</small></div></div>`;
}
function renderHybridHero(){
  const card=document.querySelector('.hero-card[data-summary="hybrid"]'); if(!card)return;
  const c=hybridCardSettings(); card.hidden=!c.visible;
  card.innerHTML=`${hybridVisualMarkup(c)}<p class="muted">${esc(c.note)}</p>`;
}
function hybridDetailMarkup(c){
  return `${detailBoxes([
    ['Ukuran pompa',c.detailPumpSize],['Sistem penggerak',c.detailSystem],['Mode diesel',c.detailDiesel],['Mode listrik',c.detailElectric],['Perpindahan penggerak',c.detailTransfer],['Keselamatan',c.detailSafety],['Perawatan',c.detailMaintenance]
  ])}<div class="detail-note">Konfigurasi kartu saat ini: ${esc(c.dieselLabel)} ${esc(c.dieselPower)} ${esc(c.shaftSymbol)} ${esc(c.electricLabel)} ${esc(c.electricPower)}.</div>`;
}
function currentUser(){
  const id=sessionStorage.getItem(SESSION); if(!id)return null;
  return getDB().users.find(u=>u.id===id)||null;
}
function audit(action,detail){
  const db=getDB();const u=currentUser();
  db.audit.unshift({id:uid('LOG'),at:new Date().toISOString(),user:u?.email||'public',action,detail});
  db.audit=db.audit.slice(0,250);saveDB(db);
}
function downloadText(filename,text,type='text/plain'){
  const blob=new Blob([text],{type}); const url=URL.createObjectURL(blob); const a=document.createElement('a');
  a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function csvCell(v){ const s=String(v??''); return /[",\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s; }
async function fileToDataURL(file,maxBytes=5000000){
  if(!file)return '';
  if(file.size>maxBytes)throw new Error('Ukuran file terlalu besar. Maksimal 5 MB.');
  if(cloudReady&&firebaseStorage&&firebaseAuth?.currentUser){
    const ext=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase();
    const safe=(file.name.replace(/[^a-z0-9._-]/gi,'-').slice(-80)||`upload.${ext}`);
    const ref=firebaseStorage.ref(`uploads/${firebaseAuth.currentUser.uid}/${Date.now()}-${safe}`);
    await ref.put(file,{contentType:file.type||'application/octet-stream'});
    return await ref.getDownloadURL();
  }
  return await new Promise((resolve,reject)=>{
    const r=new FileReader();
    r.onload=()=>resolve(r.result);
    r.onerror=()=>reject(new Error('Gagal membaca file'));
    r.readAsDataURL(file);
  });
}


